"use client";

import * as React from "react";
import { cn } from "./utils";
import { ReelVideo } from "./reel-video";

/* ── the curved row ──────────────────────────────────────────────
 * Scroll Tilted Grid turned on its side, with the tilt drawn as a curve.
 * One row of images streams from right to left around the inside of a
 * cylinder. The centre faces you flat, the ends bend toward you so each
 * end image curves along its length, and the ends fade into the page.
 *
 * A CSS box can't bend, so every tile is cut into SLICES vertical strips,
 * each a flat facet of the cylinder showing its share of the image. The
 * strips sit still inside their tile, each turned its own few degrees
 * round the cylinder's axis, and the tile (preserve-3d) is what moves: one
 * rotateY about that same axis carries the whole tile along the arc. A
 * tile is one animation, so its strips can never drift apart or show
 * different images. Only a tile's delay differs, and that sets where on
 * the arc it sits. The band is transform-only on the compositor; the fade
 * is a static mask over it.
 *
 * The only JS is a ResizeObserver that sizes the loop, and a handler that
 * hands a tile its next image each time it wraps, out of sight.
 * ─────────────────────────────────────────────────────────────── */

// Strips per tile. Each is a few degrees of arc, too little to read as a
// facet; fewer starts to show corners along the top and bottom edges. A
// tight curve wraps a tile round a wide arc, so it needs this many.
const SLICES = 16;

// Camera distance from the screen, as a multiple of the cylinder's radius.
// Just past the axis, so the ends come right up to the lens and swell; much
// further back and the row flattens out however tight the cylinder.
const CAMERA = 1.6;

/**
 * Cylinder radius, as a share of the hero's width, that puts the frame's
 * edge `bend` radians round the arc as seen through the camera:
 * r·sinθ · CAMERA / (CAMERA − 1 + cosθ) = width / 2, solved for r.
 */
function arc(bend: number) {
  return (CAMERA - 1 + Math.cos(bend)) / (2 * CAMERA * Math.sin(bend));
}

// A tile is never wider than this share of the hero, so a phone still
// shows its neighbours instead of one tile edge to edge.
const MAX_WIDTH = 55;

/**
 * Lays the loop on the cylinder. The radius puts the frame's edge `bend`
 * radians round the arc (see `arc`). Angles come back in degrees: `unit`
 * is the arc one tile-height spans, `limit` how far round a tile's centre
 * can go before the whole tile is off-screen, and `sweep` how far round
 * the loop's ends sit. The loop reaches past `limit`, so a tile only ever
 * wraps out of sight, and is rounded up to a whole number of tiles so the
 * gap never stretches.
 */
function measure(
  width: number,
  height: number,
  tile: number,
  aspect: number,
  gap: number,
  bend: number,
) {
  const h = Math.min(
    (tile / 100) * height,
    ((MAX_WIDTH / 100) * width) / aspect,
  );
  const radius = width * arc(bend);
  if (!(h > 0) || !(radius > 0))
    return { columns: 2, sweep: 0, unit: 0, limit: 0 };
  const deg = (rad: number) => (rad * 180) / Math.PI;
  const unit = deg(h / radius);
  const pitch = (aspect + gap / 100) * unit;
  const limit = deg(bend) + (aspect * unit) / 2;
  // Capped so a hero squeezed to a sliver can't mount thousands of tiles.
  const columns = Math.min(60, Math.max(2, Math.ceil((2 * limit) / pitch)));
  const round = (n: number) => +n.toFixed(4);
  const sweep = round((columns * pitch) / 2);
  return {
    columns,
    sweep,
    unit: round(unit),
    limit: round(Math.min(sweep, limit)),
  };
}

export type TiltedGridImage = {
  src: string;
  /** Optional motion clip, with src used as its still cover. */
  video?: string;
  /** Smaller recording for mobile and constrained connections. */
  videoLow?: string;
  /** Only used if you drop the decorative treatment; the band is aria-hidden. */
  alt?: string;
};

export type TiltedGridHeroProps = {
  /**
   * Images run along the row in order. A tile takes its next image each
   * time it wraps off-screen, so the whole list plays through however
   * few tiles the frame needs. Short lists simply repeat.
   */
  images: TiltedGridImage[];
  /**
   * Seconds for the row to advance by one tile. Speed is per tile, not per
   * crossing, so a phone and an ultrawide move at the same pace.
   * @default 4
   */
  speed?: number;
  /** Tile height, as a percentage of the hero's height. @default 26 */
  tileHeight?: number;
  /** Tile width divided by tile height. @default 16 / 9 */
  aspectRatio?: number;
  /** Space between tiles, as a percentage of a tile's height. @default 6 */
  gap?: number;
  /** Vertical centre of the row, as a percentage of the hero's height. @default 56 */
  axis?: number;
  /**
   * How far the row has bent round by the frame's edge, in degrees. Higher
   * curls the ends harder toward the viewer. Clamped to 5–85.
   * @default 80
   */
  curve?: number;
  /** Width of the fade at each end; zero removes the mask entirely. @default 12 */
  fade?: number;
  /** Content rendered above the band. */
  children?: React.ReactNode;
  className?: string;
  /** Pause media along with the surrounding carousel. */
  paused?: boolean;
};

export function TiltedGridHero({
  images,
  speed = 4,
  tileHeight = 26,
  aspectRatio = 16 / 9,
  gap = 6,
  axis = 56,
  curve = 80,
  fade = 12,
  children,
  className,
  paused = false,
  ...props
}: React.ComponentProps<"div"> & TiltedGridHeroProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const id = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  const orbit = `tgh-o-${id}`;
  const tile = `tgh-t-${id}`;
  const bend = (Math.min(85, Math.max(5, curve)) * Math.PI) / 180;

  // Wait for the measured layout before starting the tile animations.
  const [{ layout, generation, shown }, setReel] = React.useState<{
    layout: ReturnType<typeof measure> | null;
    generation: number;
    shown: Record<number, number>;
  }>({ layout: null, generation: 0, shown: {} });

  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const ro = new ResizeObserver(([entry]) => {
      const { width, height } = entry.contentRect;
      const next = measure(width, height, tileHeight, aspectRatio, gap, bend);
      setReel((prev) => {
        const current = prev.layout;
        if (!current || current.columns !== next.columns) {
          // Every tile needs the same animation start time and image order.
          // Rebuild the row together when its number of slots changes.
          return { layout: next, generation: prev.generation + 1, shown: {} };
        }
        if (
          current.sweep === next.sweep &&
          current.unit === next.unit &&
          current.limit === next.limit
        ) {
          return prev;
        }
        return { ...prev, layout: next };
      });
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [tileHeight, aspectRatio, gap, bend]);

  const { columns, sweep, unit, limit } =
    layout ?? measure(1200, 560, tileHeight, aspectRatio, gap, bend);

  // Every length is a multiple of the tile's height, which follows the
  // hero's height until MAX_WIDTH caps it on narrow screens.
  const u = (n: number) =>
    `calc(${+n.toFixed(4)} * min(${tileHeight}cqh, ${+(
      MAX_WIDTH / aspectRatio
    ).toFixed(4)}cqw))`;

  const r = 100 * arc(bend);
  const radius = `${+r.toFixed(3)}cqw`;
  // Out to the axis, round it, back in: a box sits on the cylinder at the
  // angle rotateY gives it.
  const turn = (deg: number) =>
    `translateZ(${radius}) rotateY(${+deg.toFixed(4)}deg) translateZ(-${radius})`;

  // Beyond `limit` a tile is wholly off-screen, so it is hidden there. The
  // loop's ends, where it wraps, fall inside that stretch, and so do tiles
  // swinging round behind the camera.
  const hide = +(((sweep - limit) / (2 * sweep || 1)) * 100).toFixed(4);
  const css =
    `@keyframes ${orbit}{` +
    `from{transform:${turn(-sweep)}}to{transform:${turn(sweep)}}` +
    `0%,${hide}%,${100 - hide}%,100%{visibility:hidden}` +
    `${hide + 0.001}%,${100 - hide - 0.001}%{visibility:visible}}` +
    // Pausing rather than removing the motion keeps the band whole: every
    // tile is already placed by its negative delay, so it freezes as a
    // finished still.
    `@media(prefers-reduced-motion:reduce){.${tile}{animation-play-state:paused}}`;

  const share = aspectRatio / SLICES;
  const duration = columns * speed;
  const mask = fade <= 0 ? 'none' : `linear-gradient(90deg,transparent,#000 ${fade}%,#000 ${
    100 - fade
  }%,transparent)`;

  return (
    <div
      ref={ref}
      className={cn("relative overflow-hidden", className)}
      {...props}
      style={{ containerType: "size", ...props.style }}
    >
      <style>{css}</style>

      <div
        aria-hidden
        className="tilted-grid-band pointer-events-none absolute inset-0 transition-opacity duration-500"
        style={{
          opacity: layout ? 1 : 0,
          // A shared vanishing point on the row's centre line, so the ends
          // grow evenly above and below it as they come toward the viewer.
          perspective: `${+(r * CAMERA).toFixed(3)}cqw`,
          perspectiveOrigin: `50% ${axis}%`,
          maskImage: mask,
          WebkitMaskImage: mask,
        }}
      >
        {layout && Array.from({ length: columns }, (_, t) => {
          // Tile `columns - 1` starts nearest the exit and tile 0 furthest
          // back, so this numbers tiles in the order they come on.
          const first = columns - 1 - t;
          const img = images[(shown[t] ?? first) % Math.max(images.length, 1)];
          const overlap = img?.video ? 2 : 1;
          return (
            <div
              key={`${generation}:${t}`}
              data-reel-tile={t}
              className={cn(tile, "absolute")}
              style={{
                left: `calc(50% - ${u(aspectRatio / 2)})`,
                top: `calc(${axis}% - ${u(0.5)})`,
                width: u(aspectRatio),
                height: u(1),
                transformStyle: "preserve-3d",
                // Tile t starts t tiles along the loop.
                animation: `${orbit} ${duration}s linear ${-t * speed}s infinite`,
              }}
              onAnimationIteration={(e) => {
                // elapsedTime counts whole loops, missed events included.
                const lap = Math.round(e.elapsedTime / duration);
                setReel((prev) => {
                  if (prev.generation !== generation) return prev;
                  const next = lap * columns + first;
                  if (prev.shown[t] === next) return prev;
                  return { ...prev, shown: { ...prev.shown, [t]: next } };
                });
              }}
            >
              {img?.video && (
                <ReelVideo
                  key={img.video}
                  src={img.video}
                  lowSrc={img.videoLow}
                  paused={paused}
                  slices={SLICES}
                  aspectRatio={aspectRatio}
                  tileWidth={u(aspectRatio)}
                />
              )}
              {Array.from({ length: SLICES }, (_, k) => (
                <div
                  key={k}
                  className="absolute top-0 overflow-hidden bg-muted"
                  style={{
                    // Every strip starts at the tile's centre and is turned
                    // round the axis to its own place on the arc.
                    left: u((aspectRatio - share) / 2),
                    // Slightly wider than its share, so neighbouring facets
                    // overlap and no hairline opens between them. The last
                    // has no neighbour to cover.
                    width:
                      k === SLICES - 1 ? u(share) : `calc(${u(share)} + ${overlap}px)`,
                    height: u(1),
                    transform: turn(
                      (aspectRatio / 2 - (k + 0.5) * share) * unit,
                    ),
                  }}
                >
                  {img ? (
                    <img
                      src={img.src}
                      alt={k === 0 ? (img.alt ?? "") : ""}
                      draggable={false}
                      loading="lazy"
                      decoding="async"
                      className="absolute top-0 max-w-none object-cover"
                      style={{
                        left: u(-k * share),
                        width: u(aspectRatio),
                        height: u(1),
                      }}
                    />
                  ) : null}
                  {img?.video && (
                    <canvas
                      className="absolute top-0 left-0"
                      style={{ height: "100%", opacity: 0 }}
                    />
                  )}
                </div>
              ))}
            </div>
          );
        })}
      </div>

      {children}
    </div>
  );
}

export default TiltedGridHero;

"use client";

import { useEffect, useRef } from 'react';

type ReelVideoProps = { src: string; lowSrc?: string; paused: boolean; slices: number; aspectRatio: number; tileWidth: string };
type Connection = EventTarget & { saveData?: boolean; effectiveType?: string; downlink?: number };
type Download = { source?: string; url?: string; pending?: Promise<string>; controller?: AbortController };

// One decoder feeds display-sized facets, once per decoded video frame.
export function ReelVideo({ src, lowSrc, paused, slices, aspectRatio, tileWidth }: ReelVideoProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const downloadRef = useRef<Download>({});
  useEffect(() => () => {
    const download = downloadRef.current;
    download.controller?.abort();
    if (download.url) URL.revokeObjectURL(download.url);
    downloadRef.current = {};
  }, [src, lowSrc]);
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    const tile = video.parentElement!;
    const root = tile.closest('.story-reel');
    const canvases = [...tile.querySelectorAll('canvas')];
    const contexts = canvases.map(canvas => canvas.getContext('2d', { alpha: false, desynchronized: true }));
    const motion = matchMedia('(prefers-reduced-motion: reduce)');
    const connection = (navigator as Navigator & { connection?: Connection }).connection;
    let near = false, visible = false, running = false, disposed = false, buffering = true;
    let frame = 0, fallbackFrame = 0, lastFrame = -1;
    let crop = { width: 0, height: 0, left: 0, top: 0 };
    let strips: { x: number; width: number }[] = [];
    let watchedDownload: Promise<string> | undefined;
    const supportsFrameCallbacks = typeof video.requestVideoFrameCallback === 'function';
    if (video.dataset.canvasSource !== src) {
      canvases.forEach(canvas => { canvas.style.opacity = '0'; });
      video.dataset.canvasSource = src;
    }
    const size = () => {
      if (!video.videoWidth || !tile.clientHeight) return;
      const width = Math.min(video.videoWidth, video.videoHeight * aspectRatio);
      const height = width / aspectRatio;
      crop = { width, height, left: (video.videoWidth - width) / 2, top: (video.videoHeight - height) / 2 };
      const renderHeight = Math.min(video.videoHeight, 480, Math.ceil(tile.clientHeight * Math.min(devicePixelRatio || 1, 1.5)));
      const renderWidth = renderHeight * aspectRatio;
      const overlap = Math.ceil(width * 2 / Math.max(1, tile.clientWidth)) + 2;
      strips = canvases.map((canvas, index) => {
        const x = index * width / slices;
        const stripWidth = Math.min(width / slices + overlap, width - x);
        const pixels = Math.ceil(stripWidth / width * renderWidth);
        if (canvas.width !== pixels || canvas.height !== renderHeight) { canvas.width = pixels; canvas.height = renderHeight; }
        canvas.style.width = `calc(${tileWidth} * ${stripWidth / width})`;
        return { x, width: stripWidth };
      });
    };
    const paint = () => {
      if (video.readyState < 2) return;
      if (!strips.length) size();
      strips.forEach((strip, index) => {
        const canvas = canvases[index];
        contexts[index]?.drawImage(video, crop.left + strip.x, crop.top, strip.width, crop.height, 0, 0, canvas.width, canvas.height);
        if (canvas.style.opacity !== '1') canvas.style.opacity = '1';
      });
    };
    const cancelFrame = () => {
      if (frame) video.cancelVideoFrameCallback(frame);
      cancelAnimationFrame(fallbackFrame); frame = 0; fallbackFrame = 0;
    };
    const nextFrame = () => {
      if (!running || disposed) return;
      if (supportsFrameCallbacks) {
        frame = video.requestVideoFrameCallback(() => { frame = 0; paint(); nextFrame(); });
      } else {
        fallbackFrame = requestAnimationFrame(() => {
          const count = video.getVideoPlaybackQuality?.().totalVideoFrames ?? video.currentTime;
          if (count !== lastFrame) { paint(); lastFrame = count; }
          nextFrame();
        });
      }
    };
    const loadSource = () => {
      const limited = matchMedia('(max-width: 700px)').matches || connection?.saveData ||
        /^(slow-)?2g$|^3g$/.test(connection?.effectiveType ?? '') || (!!connection?.downlink && connection.downlink < 2.5);
      const selected = lowSrc && (limited || video.dataset.mediaSource === lowSrc) ? lowSrc : src;
      let target = selected;
      if (selected === lowSrc) {
        const download = downloadRef.current;
        if (!download.pending) {
          download.source = selected;
          download.controller = new AbortController();
          const signal = download.controller.signal;
          download.pending = fetch(selected, { signal, cache: 'force-cache' })
            .then(response => { if (!response.ok) throw new Error('Video unavailable'); return response.blob(); })
            .then(blob => {
              if (signal.aborted) return '';
              download.url = URL.createObjectURL(blob);
              return download.url;
            }).catch(() => '');
        }
        if (watchedDownload !== download.pending) {
          watchedDownload = download.pending;
          void download.pending.then(() => { if (!disposed) sync(); });
        }
        if (!download.url) return;
        target = download.url;
      }
      video.dataset.mediaSource = selected;
      if (video.getAttribute('src') !== target) { buffering = true; video.src = target; video.preload = 'auto'; video.load(); }
    };
    const sync = () => {
      if (disposed) return;
      if (near && !paused && !motion.matches) loadSource();
      const buffered = video.buffered;
      const bufferEnd = buffered.length ? buffered.end(buffered.length - 1) : 0;
      const lightweight = !!lowSrc && video.dataset.mediaSource === lowSrc;
      const remaining = Math.max(0, (video.duration || 1.25) - video.currentTime);
      // Lightweight clips are already downloaded in full before a decoder starts.
      const needed = Math.min(lightweight ? .5 : 1.25, remaining);
      if (buffering && video.readyState >= 3 && bufferEnd - video.currentTime >= needed - .05) buffering = false;
      const active = visible && !paused && !motion.matches && !document.hidden &&
        getComputedStyle(tile).visibility !== 'hidden' && !buffering && video.readyState >= 3;
      if (active && !running) {
        running = true;
        void video.play().catch(() => { running = false; cancelFrame(); });
        paint(); nextFrame();
      } else if (!active) { running = false; video.pause(); cancelFrame(); }
    };
    const waiting = () => { buffering = true; sync(); };
    const loaded = () => { size(); sync(); };
    const resize = () => { size(); if (video.readyState >= 2) paint(); sync(); };
    const upcoming = new IntersectionObserver(([entry]) => { near = entry.isIntersecting; sync(); }, { root, rootMargin: '0px 35%' });
    const inView = new IntersectionObserver(([entry]) => { visible = entry.isIntersecting; sync(); }, { root, threshold: .01 });
    upcoming.observe(tile); inView.observe(tile);
    const observer = new ResizeObserver(resize); observer.observe(tile);
    // CSS hides tiles while they wrap behind the curved row.
    const visibilityTimer = setInterval(sync, 250);
    video.addEventListener('loadedmetadata', loaded); video.addEventListener('canplay', sync);
    video.addEventListener('progress', sync); video.addEventListener('waiting', waiting);
    motion.addEventListener('change', sync); connection?.addEventListener('change', sync);
    document.addEventListener('visibilitychange', sync); sync();
    return () => {
      disposed = true; running = false; cancelFrame(); video.pause();
      upcoming.disconnect(); inView.disconnect(); observer.disconnect(); clearInterval(visibilityTimer);
      video.removeEventListener('loadedmetadata', loaded); video.removeEventListener('canplay', sync);
      video.removeEventListener('progress', sync); video.removeEventListener('waiting', waiting);
      motion.removeEventListener('change', sync); connection?.removeEventListener('change', sync);
      document.removeEventListener('visibilitychange', sync);
    };
  }, [src, lowSrc, paused, slices, aspectRatio, tileWidth]);
  return <video ref={videoRef} data-reel-video muted loop playsInline preload="none" hidden />;
}

